#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/util.h>

#define TEST_NODE DT_NODELABEL(gpio_mmio_latch)
#define TEST_DEV DEVICE_DT_GET(TEST_NODE)
#define TEST_REG_ADDR DT_REG_ADDR(TEST_NODE)
#define TEST_NGPIOS DT_PROP(TEST_NODE, ngpios)

/* An arbitrary initial value for the output register */
#define TEST_INITIAL_OUTPUT 0xdeadbeef

static const struct device *const test_dev = TEST_DEV;
static const uint32_t test_ngpios = TEST_NGPIOS;

static void test_callback_edge_rising(const struct device *dev, struct gpio_callback *cb,
				      uint32_t pins)
{
	/* Do nothing */
}

static void test_callback_edge_falling(const struct device *dev, struct gpio_callback *cb,
					uint32_t pins)
{
	/* Do nothing */
}

static void *gpio_mmio_latch_setup(void)
{
	zassert_true(device_is_ready(test_dev), "test device not ready");
	zassert_true(test_ngpios > 0, "test device has no gpios");
	zassert_true(test_ngpios <= 32, "test device has too many gpios");

	/*
	 * The test device is just a pointer to memory. This test writes an initial value to
	 * that memory and then verifies that it can be read back. This ensures that the
	 * memory is writable and that the test has exclusive access to it.
	 */
	sys_write32(TEST_INITIAL_OUTPUT, TEST_REG_ADDR);
	zassert_equal(sys_read32(TEST_REG_ADDR), TEST_INITIAL_OUTPUT,
		      "sys_read32(TEST_REG_ADDR) not equal to TEST_INITIAL_OUTPUT");

	return NULL;
}

ZTEST(gpio_mmio_latch, test_config_in)
{
	for (uint32_t i = 0; i < test_ngpios; i++) {
		zassert_ok(gpio_pin_configure(test_dev, i, GPIO_INPUT), "gpio_pin_configure()_");
	}
}

ZTEST(gpio_mmio_latch, test_config_out)
{
	for (uint32_t i = 0; i < test_ngpios; i++) {
		zassert_ok(gpio_pin_configure(test_dev, i, GPIO_OUTPUT), "gpio_pin_configure()");
	}
}

ZTEST(gpio_mmio_latch, test_config_out_init_low)
{
	for (uint32_t i = 0; i < test_ngpios; i++) {
		zassert_ok(gpio_pin_configure(test_dev, i, GPIO_OUTPUT_LOW),
			   "gpio_pin_configure()");
	}
}

ZTEST(gpio_mmio_latch, test_config_out_init_high)
{
	for (uint32_t i = 0; i < test_ngpios; i++) {
		zassert_ok(gpio_pin_configure(test_dev, i, GPIO_OUTPUT_HIGH),
			   "gpio_pin_configure()");
	}
}

ZTEST(gpio_mmio_latch, test_set_and_get)
{
	uint32_t out_val;

	/* Set all pins to output low */
	zassert_ok(gpio_port_set_masked_raw(test_dev, MASK(test_ngpios), 0),
		   "gpio_port_set_masked_raw()");

	/* Get the raw port value */
	zassert_ok(gpio_port_get_raw(test_dev, &out_val), "gpio_port_get_raw()");
	zassert_equal(out_val, 0, "out_val not equal to 0");

	/* Set all pins to output high */
	zassert_ok(gpio_port_set_masked_raw(test_dev, MASK(test_ngpios), MASK(test_ngpios)),
		   "gpio_port_set_masked_raw()");

	/* Get the raw port value */
	zassert_ok(gpio_port_get_raw(test_dev, &out_val), "gpio_port_get_raw()");
	zassert_equal(out_val, MASK(test_ngpios), "out_val not equal to MASK(test_ngpios)");
}

ZTEST(gpio_mmio_latch, test_interrupts)
{
	int ret;
	struct gpio_callback cb_edge_rising;
	struct gpio_callback cb_edge_falling;

	gpio_init_callback(&cb_edge_rising, test_callback_edge_rising, BIT(0));
	gpio_init_callback(&cb_edge_falling, test_callback_edge_falling, BIT(1));

	ret = gpio_add_callback(test_dev, &cb_edge_rising);
	zassert_equal(ret, -ENOTSUP, "gpio_add_callback() did not return -ENOTSUP");

	ret = gpio_add_callback(test_dev, &cb_edge_falling);
	zassert_equal(ret, -ENOTSUP, "gpio_add_callback() did not return -ENOTSUP");

	ret = gpio_pin_interrupt_configure(test_dev, 0, GPIO_INT_EDGE_RISING);
	zassert_equal(ret, -ENOTSUP, "gpio_pin_interrupt_configure() did not return -ENOTSUP");

	ret = gpio_pin_interrupt_configure(test_dev, 1, GPIO_INT_EDGE_FALLING);
	zassert_equal(ret, -ENOTSUP, "gpio_pin_interrupt_configure() did not return -ENOTSUP");

	ret = gpio_remove_callback(test_dev, &cb_edge_rising);
	zassert_equal(ret, -ENOTSUP, "gpio_remove_callback() did not return -ENOTSUP");

	ret = gpio_remove_callback(test_dev, &cb_edge_falling);
	zassert_equal(ret, -ENOTSUP, "gpio_remove_callback() did not return -ENOTSUP");
}

ZTEST_SUITE(gpio_mmio_latch, NULL, gpio_mmio_latch_setup, NULL, NULL, NULL);
